<script setup>
import DevicePolicy from './DevicePolicy.vue'
import PostManagement from './PostManagement.vue'
import PeerAddress from './PeerAddress.vue'
import {networkContext,subnetHost} from './install-inputs.js'
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {api} from './api'
import {walletTranslations as translations} from './wallet-texts.js'
const emit=defineEmits(['dirty','saved'])
const props=defineProps({token:String,install:Boolean,admin:Boolean,language:{type:String,default:'ru'}})
const status=ref(null),error=ref(''),notice=ref(''),busy=ref(false),minutes=ref(30),primary=ref(1),standby=ref(2),peers=ref([])
const managementBusy=ref(false)
const network=ref(networkContext(null,location.hostname))
const tx=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const migrateLocal=ref(false),migrationConfirmation=ref(''),migrateVip=ref(false),vipConfirmation=ref('')
const availability=ref(null),availabilityBusy=ref(false),availabilityFailed=ref(false),now=ref(Date.now())
const currentAvailability=computed(()=>availability.value&&now.value-Date.parse(availability.value.checked_at)<20000?availability.value:null)
const availabilityKey=()=>JSON.stringify([status.value?.configuration?.site_id,status.value?.configuration?.local_post,status.value?.configuration?.primary_post,status.value?.configuration?.standby_post,status.value?.configuration?.generation])
const time=value=>value?new Date(value).toLocaleString(props.language==='uz'?'uz-UZ':props.language==='en'?'en-GB':'ru-RU',{timeZone:'Asia/Tashkent'}):'—'
const diagnostics=ref(null),policyDirty=ref(false),settingsDirty=ref(false)
function policyChanged(value){policyDirty.value=value;emit('dirty',value||settingsDirty.value)}
const recovery=ref([]),recoveryId=ref(null),recoveryUid=ref('')
const tr=text=>translations[text]?.[props.language]||text
const reason=value=>tr(({nv9_uncertain_owner:"Наличные для восстановления",cash_during_vip:"Наличные во время VIP",late_click_payment:"Запоздавший Click"})[value]||value)
const endpoint=()=>props.install?'/api/commissioning/wallet':props.admin?'/api/admin/wallet':'/api/owner/wallet'
const request=(url,options={})=>api(url,{token:props.token,...options})
const post=(url,data={})=>request(url,{method:'POST',body:JSON.stringify(data)})
watch(()=>JSON.stringify([minutes.value,primary.value,standby.value,peers.value,recoveryUid.value,migrateLocal.value,migrationConfirmation.value,migrateVip.value,vipConfirmation.value]),()=>{if(!busy.value){settingsDirty.value=true;emit('dirty',true)}},{flush:'sync'})
async function load(){diagnostics.value=null;availability.value=null;availabilityFailed.value=false;status.value=await request(endpoint());const c=status.value.configuration;minutes.value=c.visit_timeout_minutes;primary.value=c.primary_post;standby.value=c.standby_post||2;peers.value=Object.entries(c.peer_urls).map(([post,url])=>({post:Number(post),url}));if(!peers.value.length)peers.value=[...new Set([primary.value,standby.value,c.local_post])].map(post=>({post,url:''}));
if(props.install){try{network.value=networkContext(await request('/api/commissioning/network/status'),location.hostname)}catch{}}
for(const p of peers.value){if(p.post===c.local_post&&!p.url&&network.value.address)p.url='http://'+network.value.address}
settingsDirty.value=false;emit('dirty',policyDirty.value);if(c.enabled)checkAvailability()}
async function checkAvailability(){
 if(availabilityBusy.value||!status.value?.configuration?.enabled)return
 availabilityBusy.value=true;const key=availabilityKey()
 try{const value=await request(endpoint()+'/availability',{signal:AbortSignal.timeout(6500)});if(key===availabilityKey()){availability.value=value;availabilityFailed.value=false;now.value=Date.now()}}
 catch{if(key===availabilityKey()){availability.value=null;availabilityFailed.value=true}}
 finally{availabilityBusy.value=false}
}
function nodeTitle(node){const primary=node.post===status.value.configuration.primary_post;return primary?(node.state==='available'?tx('Главный сейчас доступен','Asosiy post hozir mavjud','Primary is currently available'):node.state==='mismatch'?tx('Главный отвечает, роли требуют сверки','Asosiy post javob bermoqda, rollarni tekshiring','Primary responds; roles need reconciliation'):tx('Главный сейчас недоступен','Asosiy post hozir mavjud emas','Primary is currently unavailable')):(node.state==='available'?tx('Резерв сейчас доступен','Zaxira post hozir mavjud','Standby is currently available'):node.state==='mismatch'?tx('Резерв отвечает, роли требуют сверки','Zaxira post javob bermoqda, rollarni tekshiring','Standby responds; roles need reconciliation'):tx('Резерв сейчас недоступен','Zaxira post hozir mavjud emas','Standby is currently unavailable'))}
const diagnosticState=value=>tr(({'in-sync':'Данные совпадают','not-configured':'Кошелёк не настроен','single-copy':'Работа с одной копией','unavailable':'Один из узлов недоступен','authority-mismatch':'Роли узлов не совпадают','protocol-mismatch':'Обновите оба узла','pending':'Есть незавершённые операции','differs':'Данные различаются — повторите проверку'})[value]||value)
async function diagnose(){diagnostics.value=await request('/api/owner/wallet/diagnostics')}
async function loadRecovery(){recovery.value=(await request('/api/owner/wallet/recovery')).credits}
async function restore(){if(!recoveryId.value||!/^[0-9A-Fa-f]{4,64}$/.test(recoveryUid.value))throw Error('Выберите остаток и укажите UID денежной карты');await post('/api/owner/wallet/recovery/'+recoveryId.value,{uid:recoveryUid.value.toUpperCase()});await loadRecovery();recoveryId.value=null;recoveryUid.value='';settingsDirty.value=false;emit('dirty',policyDirty.value);notice.value='Остаток переведён в кошелёк карты.'}
async function run(fn){if(busy.value||managementBusy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function addPeer(){const post=Array.from({length:100},(_,i)=>i+1).find(n=>!peers.value.some(p=>p.post===n));if(post)peers.value.push({post,url:''})}
async function setup(){const rows={};for(const p of peers.value){if(!Number.isInteger(p.post)||p.post<1||p.post>100||rows[p.post])throw Error('Проверьте номера постов: 1–100, без повторов');const url=p.url.trim();let parsed;try{parsed=new URL(url)}catch{throw Error(tx('Укажите IP-адрес каждого поста','Har bir postning IP manzilini kiriting','Enter each station IP address'))}
if(!subnetHost(parsed.hostname,network.value))throw Error(tx('Адрес поста '+p.post+' вне подсети или является адресом сети/рассылки','Post '+p.post+' manzili mahalliy tarmoqqa mos emas','Station '+p.post+' address is outside the subnet or is a network/broadcast address'))
if(Object.values(rows).some(v=>new URL(v).origin===parsed.origin))throw Error(tx('У постов должны быть разные IP-адреса','Postlarning IP manzillari turlicha bo‘lishi kerak','Stations must have different IP addresses'));rows[p.post]=url}await post(props.install?endpoint():'/api/admin/wallet/setup',{primary_post:primary.value,standby_post:standby.value,peer_urls:rows,migrate_local_balances:migrateLocal.value,migration_confirmation:migrationConfirmation.value,migrate_local_vip:migrateVip.value,vip_migration_confirmation:vipConfirmation.value});await load();emit('saved');notice.value='Роли сохранены. Настройте второй узел и выполните синхронизацию на главном.'}
async function timeout(){await post('/api/owner/wallet/timeout',{visit_timeout_minutes:minutes.value});await load();notice.value='Время визита сохранено. Изменение действует для новых визитов.'}
async function sync(){await post(props.install?'/api/commissioning/wallet/synchronize':'/api/owner/wallet/synchronize');await load();notice.value='Журналы сверены. Запись на главный и резервный восстановлена.'}
let pollTimer,clockTimer
function checkVisible(){if(!document.hidden&&!busy.value)checkAvailability()}
onMounted(()=>{run(load);pollTimer=setInterval(checkVisible,10000);clockTimer=setInterval(()=>{now.value=Date.now()},1000);document.addEventListener('visibilitychange',checkVisible)})
onUnmounted(()=>{clearInterval(pollTimer);clearInterval(clockTimer);document.removeEventListener('visibilitychange',checkVisible)})
</script>
<template>
<PostManagement v-if="!install&&status?.configuration?.enabled" :token="token" :language="language" :disabled="policyDirty||settingsDirty||busy" :availability="currentAvailability" @busy="managementBusy=$event" @changed="run(load)"/>
<details class="wallet-advanced" :open="install||!status?.configuration?.enabled"><summary v-if="!install&&status?.configuration?.enabled">{{tx('Кошелёк, бонусы и диагностика','Hamyon, bonuslar va diagnostika','Wallet, bonuses and diagnostics')}}</summary>
<DevicePolicy v-if="!admin&&!managementBusy&&status?.configuration?.enabled" :install="install" :token="token" :language="language" @dirty="policyChanged"/>
<section class="card content wallet-settings"><h2>{{ tr("Общий кошелёк и резервный пост") }}</h2>
<p v-if="error" class="message error" role="alert">{{tr(error)}}</p><p v-if="notice" class="message success" role="status">{{tr(notice)}}</p>
<p v-if="busy" role="status">{{ tr("Проверка…") }}</p><button class="quiet" :disabled="managementBusy||busy" @click="run(load)">{{ tr("Обновить состояние") }}</button>
<template v-if="status"><p class="muted">{{tr('Мойка')}}: {{status.configuration.site_id||tr('не активирована')}} · {{tr('Этот пост')}}: {{status.configuration.local_post}}</p>
<template v-if="!status.configuration.enabled"><p>{{ tr("Главный хранит кошелёк, VIP и управляет Telegram. Резервный получает подтверждённые операции. Каждый пост нужно подключить к одной мойке.") }}</p>
<div class="fields"><label>{{ tr("Главный пост") }}<input v-model.number="primary" type="number" min="1" max="100"/></label><label>{{ tr("Резервный пост") }}<input v-model.number="standby" type="number" min="1" max="100"/></label></div>
<p v-if="network.address && !status.configuration.enabled" class="muted">{{tx('Этот пост','Ushbu post','This station')}}: {{network.address}}{{network.prefix!==null?'/'+network.prefix:''}}. {{tx('Номер поста и последнее число IP — разные значения.','Post raqami va IP manzilining oxirgi soni — alohida qiymatlar.','Station number and the last IP number are separate values.')}}</p><div v-for="(p,i) in peers" :key="i" class="wallet-peer"><label>{{ tr("Номер") }}<input v-model.number="p.post" type="number" min="1" max="100"/></label><PeerAddress v-model="p.url" :context="network" :post="p.post" :language="language"/><button class="quiet" :disabled="managementBusy||busy" @click="peers.splice(i,1)">{{ tr("Удалить") }}</button></div>
<label class="check"><input v-model="migrateLocal" type="checkbox"/>{{tr('Сохранить локальные остатки для переноса Owner')}}</label><p v-if="migrateLocal" class="muted">{{tr('Локальные денежные карты будут заблокированы, деньги сохранятся. После настройки Owner переносит каждую карту отдельно. Для VIP включите сохранение ниже.')}}</p><label v-if="migrateLocal">{{tr('Введите')}} MIGRATE LOCAL BALANCES POST {{status.configuration.local_post}}<input v-model="migrationConfirmation" autocomplete="off"/></label>
<label class="check"><input v-model="migrateVip" type="checkbox"/>{{tr('Сохранить локальные VIP для переноса Owner')}}</label><p v-if="migrateVip" class="muted">{{tr('VIP-карты будут заморожены. Профили, дневные допуски и VIP-остатки сохранятся. После установки Owner переносит их и завершает сверку всех постов.')}}</p><label v-if="migrateVip">{{tr('Введите')}} MIGRATE LOCAL VIP POST {{status.configuration.local_post}}<input v-model="vipConfirmation" autocomplete="off"/></label>
<div class="actions"><button class="quiet" :disabled="managementBusy||busy" @click="addPeer()">{{ tr("Добавить пост") }}</button><button class="primary" :disabled="managementBusy||busy||!status.configuration.site_id" @click="run(setup)">{{ install?tr("Сохранить роли"):tx("Подключить резерв","Zaxirani ulash","Connect standby") }}</button></div>
</template>
<template v-else><dl class="wallet-status"><dt>{{ tr("Главный") }}</dt><dd>{{tr('Пост')}} {{status.configuration.primary_post}}</dd><dt>{{ tr("Резервный") }}</dt><dd>{{tr('Пост')}} {{status.configuration.standby_post}}</dd><dt>{{ tr("Режим") }}</dt><dd>{{status.configuration.single_node?tr('Одна серверная копия'):tr('Подтверждение на двух узлах')}}</dd><dt>{{ tr("Операции на сверку") }}</dt><dd>{{status.pending_count||0}}</dd><dt>{{tx('Последняя синхронизация','Oxirgi sinxronlash','Last synchronization')}}</dt><dd>{{status.last_synchronization_at?time(status.last_synchronization_at):status.configuration.standby_ready?tx('Подтверждена ранее; время не сохранено','Avval tasdiqlangan; vaqt saqlanmagan','Previously confirmed; time was not recorded'):tx('Для текущих ролей ещё не подтверждена','Joriy rollar uchun hali tasdiqlanmagan','Not yet confirmed for the current roles')}}</dd></dl>
<section class="wallet-live" aria-live="polite"><h3>{{tx('Доступность сейчас','Hozirgi ulanish','Current availability')}}</h3><template v-if="currentAvailability"><div v-for="node in currentAvailability.nodes" :key="node.post" class="wallet-live-node" :class="node.state"><strong>{{nodeTitle(node)}} · {{tr('Пост')}} {{node.post}}</strong><p v-if="node.reason==='authentication_failed'">{{tx('Не удалось подтвердить подключение к этому кошельку. Завершите установку поста и затем синхронизируйте узлы.','Ushbu hamyonga ulanish tasdiqlanmadi. Postni sozlashni yakunlab, tugunlarni sinxronlang.','The peer could not authenticate for this wallet. Finish station setup, then synchronize the nodes.')}}</p><p v-else-if="node.state==='unavailable'">{{tx('Проверьте питание, локальную сеть и настройку поста.','Quvvat, mahalliy tarmoq va post sozlamalarini tekshiring.','Check power, the local network and station setup.')}}</p></div><p class="muted">{{tx('Проверено','Tekshirildi','Checked')}}: {{time(currentAvailability.checked_at)}} · {{tx('Обновление каждые 10 секунд','Har 10 soniyada yangilanadi','Updates every 10 seconds')}}</p></template><p v-else>{{availabilityBusy?tx('Проверяем подключение…','Ulanish tekshirilmoqda…','Checking connectivity…'):availabilityFailed?tx('Не удалось проверить доступность. Это не подтверждает отказ резерва.','Ulanishni tekshirib bo‘lmadi. Bu zaxira ishlamayotganini tasdiqlamaydi.','Could not check availability. This does not confirm a standby failure.'):tx('Нет свежей проверки доступности','Ulanish bo‘yicha yangi tekshiruv yo‘q','No recent availability check')}}</p><p class="muted">{{tx('Доступность постов не означает, что их журналы совпадают. Для полной сверки используйте «Проверить оба узла».','Postlar mavjudligi jurnallar mosligini anglatmaydi. To‘liq tekshiruv uchun «Ikkala tugunni tekshirish»dan foydalaning.','Reachability does not prove journal agreement. Use Check both nodes for full verification.')}}</p><button class="quiet" :disabled="managementBusy||busy||availabilityBusy" @click="checkAvailability">{{tx('Проверить доступность','Ulanishni tekshirish','Check availability')}}</button></section>
<div v-if="install && status.role==='primary'" class="wallet-operation"><p>{{tx('После настройки второго поста нажмите «Синхронизировать и проверить».','Ikkinchi post sozlangach, «Sinxronlash va tekshirish»ni bosing.','After setting up the second station, synchronize and verify.')}}</p><button class="primary" :disabled="managementBusy||busy" @click="run(sync)">{{tr('Синхронизировать и проверить')}}</button></div><template v-if="!install&&!admin"><div class="wallet-operation"><h3>{{tr('Состояние синхронизации')}}</h3><p>{{tx('Сверка журналов и ролей выполняется отдельно от проверки доступности.','Jurnallar va rollar ulanishdan alohida tekshiriladi.','Journal and role verification is separate from the connectivity check.')}}</p><button class="quiet" :disabled="managementBusy||busy" @click="run(diagnose)">{{tr('Проверить оба узла')}}</button><template v-if="diagnostics"><p role="status"><strong>{{diagnosticState(diagnostics.state)}}</strong></p><p class="muted">{{tr('Время проверки')}}: {{new Date(diagnostics.checked_at).toLocaleString(language==='uz'?'uz-UZ':language==='en'?'en-GB':'ru-RU')}}</p><div v-for="node in diagnostics.nodes" :key="node.post" class="wallet-node"><strong>{{tr('Пост')}} {{node.post}} · {{node.online?tr('Доступен'):tr('Недоступен')}}</strong><template v-if="node.online"><p>{{tr('Поколение')}}: {{node.proof.generation}} · {{tr('Операции')}}: {{node.proof.operation_count}} · {{tr('Операции на сверку')}}: {{node.proof.pending_count}}</p><p class="wallet-digest">{{tr('Журнал')}}: {{node.proof.journal_digest}}<br/>{{tr('Карты, квитанции и VIP')}}: {{node.proof.state_digest}}</p></template><p v-else>{{node.error}}</p></div><p class="muted">{{tr('Проверка не переключает роли. Данные могут измениться между снимками; при различии повторите проверку.')}}</p></template></div><label>{{ tr("Завершать визит через, минут") }}<input v-model.number="minutes" type="number" min="1" max="1440"/></label><p class="muted">{{ tr("По умолчанию 30 минут после возврата остатка. Повторное прикладывание до этого срока не обновляет бесплатную паузу.") }}</p><button class="primary" :disabled="managementBusy||busy||status.role!=='primary'" @click="run(timeout)">{{ tr("Сохранить время") }}</button>
<div v-if="status.role==='primary'" class="wallet-operation"><h3>{{ tr("Восстановить резервирование") }}</h3><p>{{ tr("Включите второй узел. Он станет резервным; главным автоматически не станет.") }}</p><button class="primary" :disabled="managementBusy||busy" @click="run(sync)">{{ tr("Синхронизировать и проверить") }}</button></div>
<div class="wallet-operation"><h3>{{ tr("Восстановление денег") }}</h3><p>{{ tr("Запоздавшие платежи без привязанной карты и наличные во время VIP сохраняются отдельно. Проверив клиента и платёж, переведите остаток на его денежную карту. Повтор после сбоя допускается только на ту же карту.") }}</p><button class="quiet" :disabled="managementBusy||busy" @click="run(loadRecovery)">{{ tr("Показать сохранённые остатки") }}</button><div v-for="r in recovery" :key="r.id" class="wallet-operation"><strong>#{{r.id}} · {{Number(r.amount_sum).toLocaleString('ru-RU')}} so‘m</strong><p>{{reason(r.reason)}} · {{r.target_uid||tr('Карта ещё не указана')}}</p><button class="quiet" :disabled="managementBusy||busy" @click="recoveryId=r.id;recoveryUid=r.target_uid||''">{{ tr("Выбрать") }}</button></div><template v-if="recoveryId"><label>{{ tr("UID денежной карты") }}<input v-model="recoveryUid" maxlength="64" autocomplete="off"/></label><button class="primary" :disabled="managementBusy||busy" @click="run(restore)">{{tr('Перевести остаток')}} #{{recoveryId}}</button></template></div>
</template>
</template></template>
</section>
</details>
</template>
<style scoped>
.wallet-live{border-top:1px solid var(--border);padding-top:24px;margin:24px 0}.wallet-live-node{padding:14px 18px;margin:12px 0;border-left:4px solid var(--border);background:var(--surface-alt,transparent);border-radius:6px}.wallet-live-node.available{border-color:#258b61}.wallet-live-node.unavailable,.wallet-live-node.mismatch{border-color:#d46627}.wallet-live-node p{margin:10px 0 0;line-height:1.6}.wallet-node{margin-top:16px;padding:16px;border:1px solid var(--border);border-radius:8px}.wallet-digest{overflow-wrap:anywhere;font-family:monospace;font-size:13px}.wallet-settings{margin-top:24px;padding:28px 30px}.wallet-settings>p{line-height:1.6;margin:20px 0}.wallet-settings .fields{padding:0;margin:24px 0}.wallet-settings label{display:flex;flex-direction:column;gap:12px}.wallet-settings label.check{flex-direction:row;align-items:flex-start}.wallet-settings .actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}.wallet-settings .wallet-operation>p{line-height:1.6;margin:16px 0}.wallet-settings .wallet-operation>label{max-width:640px}.wallet-settings h3{margin:0 0 16px}.wallet-peer{display:flex;gap:16px;align-items:end;margin:16px 0}.wallet-peer label:first-child{max-width:120px}.wallet-peer label:nth-child(2){flex:1}.wallet-status{display:grid;grid-template-columns:1fr 1fr;gap:12px}.wallet-status dd{margin:0;font-weight:600}.wallet-operation{border-top:1px solid var(--border);padding-top:24px;margin-top:24px}.wallet-operation label{margin-bottom:16px}@media(max-width:650px){.wallet-settings{padding:20px}.wallet-settings .fields{grid-template-columns:1fr}.wallet-status{grid-template-columns:1fr}.wallet-settings .wallet-operation>label{max-width:100%}.wallet-peer{flex-wrap:wrap}.wallet-peer label:nth-child(2){min-width:200px}}
</style>
